output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are not allowed in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_into_single_file_aisle",
    "text": "An agent must not push a cart from an open aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "notSingleFileShelfAisle": {
          "not": "singleFileShelfAisle"
        }
      },
      "events": {
        "cartEntersSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              "notSingleFileShelfAisle"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntersSingleFileAisle"
    }
  },
  {
    "id": "no_pushing_north_from_cart_parking_mouth",
    "text": "At the mouth of a narrow product aisle, carts must not be pushed north into the aisle.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartParkingMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "cartless_walking_only_for_narrow_aisle_trip",
    "text": "Walking without a cart is allowed only during the narrow-aisle excursion or at its parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "permittedCartlessTripZone": {
          "or": [
            "singleFileShelfAisle",
            "cartParkingMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "permittedCartlessTripZone"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_single_file_pick",
    "text": "After taking an item on foot in a single-file shelf aisle, the agent must return to the parked cart and take it back.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartlessSingleFileShelfPick": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveParkedCart": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFileShelfPick",
      "discharge": "retrieveParkedCart"
    }
  },
  {
    "id": "reclaim_cart_after_parking",
    "text": "Whenever a cart is parked at a narrow-aisle mouth, it must be reclaimed before leaving.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "cartParkingMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "retrieveCartAtMouth": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "cartParkingMouth",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "retrieveCartAtMouth"
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions from open or two-wide aisles must be performed while holding the cart.",
    "abstraction": {
      "state_properties": {
        "openShelfServiceCell": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfServiceCell",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "only_set_down_cart_at_parking_mouth",
    "text": "A cart may be set down only at designated narrow-aisle parking mouths.",
    "abstraction": {
      "state_properties": {
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "setDownCartAwayFromMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "cartParkingMouth"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "setDownCartAwayFromMouth"
    }
  }
]
